    src = os.environ.get("GRADE_V5_MODULE")
    if src:
        spec = importlib.util.spec_from_file_location("grade_v5_under_test", src)
        mod = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(mod)
        return mod
    import grade_v5 as mod
    return mod


