def projections_for(
    kind: str, projections: Optional[Mapping[str, Iterable[str]]] = None
) -> frozenset[str]:
    """The enumerated views for ``kind`` under this enumeration."""
    table = DEFAULT_PROJECTIONS if projections is None else projections
