    if m:
        ref = m.group(1).strip()
    return {"tool_calls": [{"function": {"name": "fetch",
                                        "arguments": {"ref": ref}}}]}


#: Tool names a fetch-arm reply may use when the caller does not supply the set the run
#: actually DECLARED.  ``fetch`` is what the ARM_D prompt teaches (``fetch(ref=...)``);
#: ``read_file`` is what the wire schema declares (``TOOL_NAMES`` in ``run_longrun``).
#: Keeping both here is what stops the parser and the wire schema drifting apart again:
#: a ``read_file`` call used to be filtered out at the name check, so ``_calls`` came
#: back empty, no follow-up was bought, and the checkpoint scored ``unparsed``.
DEFAULT_FETCH_TOOL_NAMES: Tuple[str, ...] = ("fetch", "read_file")


def _accepted_tool_names(tool_names: Any) -> Tuple[str, ...]:
    """The names this parse accepts: the caller's declared set, else the default."""
    if tool_names is None:
        return DEFAULT_FETCH_TOOL_NAMES
    if isinstance(tool_names, str):
        tool_names = (tool_names,)
    try:
        names = tuple(str(n) for n in tool_names if n)
    except TypeError:
        return DEFAULT_FETCH_TOOL_NAMES
    return names or DEFAULT_FETCH_TOOL_NAMES


def parse_fetch_calls(assistant_message: Any,
                      tool_names: Any = None) -> List[Dict[str, Any]]:
    """Structured fetch calls in one assistant message.

    ``tool_names`` is the set of tool names the run DECLARED (``--tools``); a call whose
    name is outside it is rejected -- not silently rewritten into a fetch.  ``None``
    falls back to :data:`DEFAULT_FETCH_TOOL_NAMES`, so a caller that does not know the
    declared set still services both the prompt-taught ``fetch`` and the wire's
    ``read_file``.  A call with no name at all is still parsed, as it always was.
    """
    out: List[Dict[str, Any]] = []
    if not isinstance(assistant_message, dict):
        return out
    calls = assistant_message.get("tool_calls")
    if not isinstance(calls, list):
        return out
    accepted = _accepted_tool_names(tool_names)

    return {k: result[k] for k in sorted(result)}


def _as_int(value, default=0):
    try:
        return int(value)
    except (TypeError, ValueError):
        return default


def fetch(
    table: Mapping[str, PointerEntry],
    ref: str,
    byte_range: Tuple[int, int] = None,
    *,
    budget_tokens: int,
    tokenizer,
    tool_call_id=None,
    task_id=None,
) -> FetchResult:
    safe_ref = "" if ref is None else str(ref)
    # normalise table
    if not isinstance(table, Mapping):
        table = {}
    entry = table.get(safe_ref) if hasattr(table, "get") else None
    if entry is None and safe_ref in table:
        try:
            entry = table[safe_ref]
        except (KeyError, TypeError):
            entry = None

    if entry is None:
        return FetchResult(ref=safe_ref, outcome=NOT_FOUND, text=None, body_tokens=0, truncated=False, tool_call_id=tool_call_id)

    state = getattr(entry, "state", None)
    if isinstance(entry, Mapping):
        state = entry.get("state", state)

    if state == "live":
        outcome = OK
    elif state in ("stale", "revoked"):
        outcome = STALE_OR_REVOKED
    elif state == "ungranted":
        outcome = SCOPE_UNGRANTED
    else:
        # unknown state treated as not found-ish; keep deterministic
        outcome = NOT_FOUND

    if outcome != OK:
        return FetchResult(ref=safe_ref, outcome=outcome, text=None, body_tokens=0, truncated=False, tool_call_id=tool_call_id)

    body = None
    entry_body = getattr(entry, "body", None)
    if entry_body is None and isinstance(entry, Mapping):
        entry_body = entry.get("body", None)
    if entry_body is not None:
        body = entry_body
    else:
        _task_id_specified = task_id is not None
        if task_id is None:
            task_id = getattr(entry, "task_id", None)
            if isinstance(entry, Mapping):
                task_id = entry.get("task_id", task_id)
        tid = "" if task_id is None else str(task_id)
        key = (tid, safe_ref)
        if key in _BODIES:
            body = _BODIES[key]
        elif not _task_id_specified:
            candidates = [v for (t, r), v in _BODIES.items() if r == safe_ref]
            if len(candidates) == 1:
                body = candidates[0]
            elif len(candidates) == 0:
                raise PtrStoreMissError(
                    f"no stored body for ref {safe_ref!r} (task_id={tid!r})"
                )
            else:
                raise PtrStoreMissError(
